mapper.select:
SELECT DISTINCT witnesses.course_id FROM (
 SELECT MIN(c.id) AS course_id FROM learning_course c JOIN learning_enrollment e ON e.course_id=c.id
 WHERE c.mentor_id=#{mentorId} AND c.status='PUBLISHED' AND c.deleted=0 AND e.active=1
 AND e.student_id IN #{id}
 GROUP BY e.student_id
) witnesses ORDER BY witnesses.course_id

SELECT m.id,m.body,m.sent_at,u.nick_name AS mentor_name FROM encouragement_recipient r
JOIN encouragement_message m ON m.id=r.message_id JOIN sys_user u ON u.id=m.mentor_id
WHERE r.student_id=#{studentId} AND m.id=#{id}
